#include "mem_init.h"

#include "scamptrie_dynamic.h"
#include "trie_graph.h"

#include <algorithm>
#include <map>
#include <vector>

namespace {

// Bit writer for one 256-bit row; fields are packed LSB first from the record
// start (bit 0 of a cell, or bit 128 for the upper cell of a row).
struct BitWriter {
    std::bitset<256>& bits;
    int pos;
    void w(uint64_t value, int n) {
        for (int i = 0; i < n; ++i)
            bits[static_cast<size_t>(pos + i)] = ((value >> i) & 1ULL) != 0ULL;
        pos += n;
    }
};

// 32-bit child record: key6 | stage4<<6 | cell22<<10.
uint64_t pack_child(uint8_t key, int stage, uint32_t cell) {
    return (static_cast<uint64_t>(key & 0x3F)) |
           (static_cast<uint64_t>(stage & 0xF) << 6) |
           (static_cast<uint64_t>(cell & 0x3FFFFF) << 10);
}

// The whole normalized left-aligned 64-bit fragment relative to the forest
// origin; host bits are clear.
uint64_t pack_fragment(const PrefixRec& p, int origin) {
    int rel = p.len - origin;
    if (origin == 0) return keep_top(p.addr.hi, rel);
    if (origin == 16) return get_bits(p.addr, 16, rel) << (64 - rel);
    return keep_top(p.addr.lo, rel);
}

} // namespace

MemInit::MemInit(ScampTrieDynamic* trie) : trie_(trie) {}

ImageData MemInit::capture() {
    ImageData img;

    Graph g = build_graph(trie_->fib());

    // ---- stage assignment -------------------------------------------------
    // Children must live in a strictly lower stage than their parent.  Placing
    // every node of trie level t in stage 10-t satisfies that and keeps every
    // forest root in the head stage.
    for (size_t i = 0; i < g.owned.size(); ++i) {
        GNode* n = g.owned[i];
        n->stage = 10 - n->level;
    }

    // ---- placement --------------------------------------------------------
    // Bulk children of a TYPE3 node share one lower stage and occupy
    // contiguous two-cell slots in increasing bulk-key order.
    std::vector<std::vector<const GNode*> > groups(static_cast<size_t>(RAM_NUM));
    for (size_t i = 0; i < g.owned.size(); ++i) {
        const GNode* n = g.owned[i];
        if (n->type != 3) continue;
        int child_stage = 10 - (n->level + 1);
        for (size_t c = 0; c < n->children.size(); ++c) {
            n->children[c]->bulk = true;
            groups[static_cast<size_t>(child_stage)].push_back(n->children[c]);
        }
    }

    std::vector<std::vector<GNode*> > by_stage(static_cast<size_t>(RAM_NUM));
    for (size_t i = 0; i < g.owned.size(); ++i)
        by_stage[static_cast<size_t>(g.owned[i]->stage)].push_back(g.owned[i]);

    for (int s = 0; s < RAM_NUM; ++s) {
        uint32_t off = 0;
        // bulk groups (two cells each, in key order)
        for (size_t i = 0; i < groups[static_cast<size_t>(s)].size(); ++i) {
            GNode* c = const_cast<GNode*>(groups[static_cast<size_t>(s)][i]);
            c->cell = off;
            c->span = 2;
            off += 2;
        }
        // ordinary full records start at even cell offsets
        for (size_t i = 0; i < by_stage[static_cast<size_t>(s)].size(); ++i) {
            GNode* n = by_stage[static_cast<size_t>(s)][i];
            if (n->bulk) continue;
            if (n->type == 2 || n->type == 3 || n->type == 5) {
                n->cell = off;
                n->span = 2;
                off += 2;
            }
        }
        // ordinary half records fill the remaining cells densely
        for (size_t i = 0; i < by_stage[static_cast<size_t>(s)].size(); ++i) {
            GNode* n = by_stage[static_cast<size_t>(s)][i];
            if (n->bulk) continue;
            if (n->type == 1 || n->type == 4) {
                n->cell = off;
                n->span = 1;
                off += 1;
            }
        }
        img.cells[static_cast<size_t>(s)] = off;
        img.banks[static_cast<size_t>(s)].assign((off + 1) / 2, std::bitset<256>());
    }

    // ---- NI vector and bitmap dictionary ---------------------------------
    std::vector<GNode*> order;
    for (int s = 0; s < RAM_NUM; ++s) {
        std::vector<GNode*>& v = by_stage[static_cast<size_t>(s)];
        std::sort(v.begin(), v.end(),
                  [](const GNode* a, const GNode* b) { return a->cell < b->cell; });
        order.insert(order.end(), v.begin(), v.end());
    }
    std::vector<uint64_t> patterns;
    uint32_t ni_total = 0;
    for (size_t i = 0; i < order.size(); ++i) {
        GNode* n = order[i];
        if (n->type == 4 || n->type == 5) continue;
        if (n->ni_count > 0) {
            n->ni_base = ni_total;
            ni_total += n->ni_count;
        } else {
            n->ni_base = 0;
        }
        patterns.push_back(n->ni_bitmap);
    }
    std::sort(patterns.begin(), patterns.end());
    patterns.erase(std::unique(patterns.begin(), patterns.end()), patterns.end());
    img.bitmaps = patterns;
    for (size_t i = 0; i < order.size(); ++i) {
        GNode* n = order[i];
        if (n->type == 4 || n->type == 5) continue;
        std::vector<uint64_t>::const_iterator it =
            std::lower_bound(img.bitmaps.begin(), img.bitmaps.end(), n->ni_bitmap);
        n->bitmap_id = static_cast<uint16_t>(it - img.bitmaps.begin());
    }
    img.nexthops.assign(ni_total, 0);
    for (size_t i = 0; i < order.size(); ++i) {
        GNode* n = order[i];
        if (n->type == 4 || n->type == 5) continue;
        for (uint32_t j = 0; j < n->ni_count; ++j)
            img.nexthops[n->ni_base + j] = n->pfx[j].hop;
    }

    // ---- record packing ---------------------------------------------------
    for (size_t i = 0; i < order.size(); ++i) {
        GNode* n = order[i];
        std::bitset<256>& row = img.banks[static_cast<size_t>(n->stage)][n->cell / 2];
        int off = 128 * static_cast<int>(n->cell & 1u);
        BitWriter w{row, off};
        w.w(static_cast<uint64_t>(n->type), 3);
        w.w(n->bmp, 22);
        if (n->type == 4 || n->type == 5) {
            int cnt = (n->type == 4) ? 1 : 2;
            for (int j = 0; j < cnt; ++j) {
                w.w(pack_fragment(n->pfx[static_cast<size_t>(j)], n->origin), 64);
                w.w(static_cast<uint64_t>(n->pfx[static_cast<size_t>(j)].len - n->origin), 8);
                w.w(n->pfx[static_cast<size_t>(j)].hop, 22);
            }
            w.w(0, (n->type == 4) ? 9 : 43);
            continue;
        }
        w.w(n->bitmap_id, 16);
        w.w(n->ni_base, 22);
        if (n->type == 1 || n->type == 2) {
            int slots = (n->type == 1) ? 2 : 6;
            for (int j = 0; j < slots; ++j) {
                if (static_cast<size_t>(j) < n->children.size())
                    w.w(pack_child(n->keys[static_cast<size_t>(j)],
                                   n->children[static_cast<size_t>(j)]->stage,
                                   n->children[static_cast<size_t>(j)]->cell), 32);
                else
                    w.w(CHILD_ABSENT, 32);
            }
            w.w(0, 1);
        } else { // TYPE3: every child is a bulk child
            uint64_t bulk_bitmap = 0;
            for (size_t j = 0; j < n->children.size(); ++j)
                bulk_bitmap |= 1ULL << n->keys[j];
            int cstage = 10 - (n->level + 1);
            uint32_t base = n->children[0]->cell;
            w.w(bulk_bitmap, 64);
            w.w(base, 22);
            w.w(static_cast<uint64_t>(cstage), 4);
            for (int j = 0; j < 3; ++j) w.w(CHILD_ABSENT, 32);
            w.w(0, 7);
        }
    }

    // ---- roots and fronts -------------------------------------------------
    if (g.root0 != nullptr) {
        img.root.stage = g.root0->stage;
        img.root.cell = g.root0->cell;
    } else {
        img.root.stage = -1;
        img.root.cell = 0;
    }
    for (size_t i = 0; i < g.front16.size(); ++i) {
        ImageFront f;
        f.key = g.front16[i].first;
        f.loc.stage = g.front16[i].second->stage;
        f.loc.cell = g.front16[i].second->cell;
        img.front16.push_back(f);
    }
    for (size_t i = 0; i < g.front64.size(); ++i) {
        ImageFront f;
        f.key = g.front64[i].first;
        f.loc.stage = g.front64[i].second->stage;
        f.loc.cell = g.front64[i].second->cell;
        img.front64.push_back(f);
    }
    return img;
}
