namespace {

static const char* DBG_ENV = "SCAMP_DEBUG";
static bool dbg() {
    static int v = std::getenv("SCAMP_DEBUG") ? 1 : 0;
    return v != 0;
}
#define VDBG(...) do { if (dbg()) { std::fprintf(stderr, __VA_ARGS__); } } while (0)

struct ChildRef {
    uint8_t key = 0;
    int stage = 0;
    uint32_t cell = 0;
    bool bulk = false;
---
public:
    bool run(const ImageData& d);

private:
    const ImageData* d_ = nullptr;
    std::vector<std::vector<uint8_t> > covered_;
    std::vector<PNode> nodes_;
    std::map<std::pair<int, uint32_t>, size_t> index_;
    std::vector<PrefixRec> fib_;

    bool fail(int why) const {
        VDBG("validator fail %d\n", why);
        return false;
    }
    bool parse(int stage, uint32_t cell, bool bulk, int origin, int level, const ip6_t& region);
    bool finish();
    bool match(const GNode* g, size_t idx);
    bool read_child(uint64_t v, int stage, ChildRef& out);
};

bool Validator::run(const ImageData& d) {

const int depth = origin + 6 * level;
if (depth > max_len) return fail(11);
if (stage < 0 || stage >= RAM_NUM) return fail(12);
if (cell >= d_->cells[static_cast<size_t>(stage)]) return fail(13);

const std::bitset<256>& bits =
    d_->banks[static_cast<size_t>(stage)][cell / 2];
const int off = 128 * static_cast<int>(cell & 1u);
BitReader rd{bits, off};

const uint32_t type = static_cast<uint32_t>(rd.r(3));
if (type < 1 || type > 5) return fail(14);
const uint32_t ordinary = (type == 1 || type == 4) ? 1u : 2u;
const uint32_t span = bulk ? 2u : ordinary;
if (span == 2u && (cell & 1u)) return fail(15);       // full records: even cells
if (static_cast<uint64_t>(cell) + span > d_->cells[static_cast<size_t>(stage)])
    return fail(16);
std::vector<uint8_t>& cov = covered_[static_cast<size_t>(stage)];
for (uint32_t i = 0; i < span; ++i) {
    if (cov[cell + i]) return fail(17);               // every node has one parent
    cov[cell + i] = 1;
}
if (span == 2u && ordinary == 1u) {                // zero padded upper half
    if (!rd.zero(128, 128)) return fail(18);
}

PNode pn;
pn.stage = stage;
pn.cell = cell;
pn.span = span;
pn.origin = origin;
pn.level = level;
pn.depth = depth;
pn.region = region;
pn.type = static_cast<int>(type);
pn.bmp = static_cast<uint32_t>(rd.r(22));
pn.bulk_stage = -1;

std::vector<ChildRef> refs;

if (type == 4 || type == 5) {
    const int cnt = (type == 4) ? 1 : 2;
    for (int i = 0; i < cnt; ++i) {
        const uint64_t frag = rd.r(64);
        const int rel = static_cast<int>(rd.r(8));
        const uint32_t hop = static_cast<uint32_t>(rd.r(22));
        if (hop == HOP_NULL) return fail(19);         // hop fields are never null
        if (origin == 0) { if (rel < 0 || rel > 16) return fail(20); }
        else if (origin == 16) { if (rel < 1 || rel > 48) return fail(21); }
        else { if (rel < 1 || rel > 64) return fail(22); }
        if (origin + rel < depth) return fail(23);    // global length >= node depth
        if (frag & low_mask(64 - rel)) return fail(24); // host bits must be clear
        PrefixRec p = make_prefix(origin, region, rel, frag, hop);
        if (!prefix_of(region, depth, p.addr)) return fail(25); // belongs to region
        pn.pfx.push_back(p);
    }
    if (type == 5 && pn.pfx[0].addr == pn.pfx[1].addr && pn.pfx[0].len == pn.pfx[1].len)
        return fail(26);                              // distinct prefixes
    if (!rd.zero(rd.pos, (type == 4) ? 9 : 43)) return fail(27);
} else {
    pn.bitmap_id = static_cast<uint16_t>(rd.r(16));
    pn.ni_base = static_cast<uint32_t>(rd.r(22));
    if (pn.bitmap_id >= d_->bitmaps.size()) return fail(28);
    const uint64_t bm = d_->bitmaps[pn.bitmap_id];
    if (bm & 1ULL) return fail(29);                   // bit 0 is unused
    pn.ni_bitmap = bm;
    pn.ni_count = static_cast<uint32_t>(popcnt64(bm));
    if (pn.ni_count == 0) {
        if (pn.ni_base != 0) return fail(30);         // empty arrays have base 0
    } else if (static_cast<uint64_t>(pn.ni_base) + pn.ni_count >
               d_->nexthops.size()) {
        return fail(31);
    }

    if (type == 1 || type == 2) {
        const int slots = (type == 1) ? 2 : 6;
        int present = 0;
        uint32_t prev_key = 0;
        bool absent_seen = false;
        for (int i = 0; i < slots; ++i) {
            const uint64_t v = rd.r(32);
            if (v == CHILD_ABSENT) { absent_seen = true; continue; }
            if (absent_seen) return fail(32);         // absent records come last
            ChildRef c;
            if (!read_child(v, stage, c)) return fail(33);
            if (present > 0 && c.key <= prev_key) return fail(34);
            prev_key = c.key;
            present++;
            refs.push_back(c);
        }
        if (type == 2 && present < 3) return fail(35);
        if (!rd.zero(rd.pos, 1)) return fail(36);
    } else { // TYPE3
        pn.bulk_bitmap = rd.r(64);
        pn.bulk_base = static_cast<uint32_t>(rd.r(22));
        pn.bulk_stage = static_cast<int>(rd.r(4));
        int present = 0;
        uint32_t prev_key = 0;
        bool absent_seen = false;
        for (int i = 0; i < 3; ++i) {
            const uint64_t v = rd.r(32);
            if (v == CHILD_ABSENT) { absent_seen = true; continue; }
            if (absent_seen) return fail(37);
            ChildRef c;
            if (!read_child(v, stage, c)) return fail(38);
            if (present > 0 && c.key <= prev_key) return fail(39);
            if (pn.bulk_bitmap & (1ULL << c.key)) return fail(40); // disjoint keys
            prev_key = c.key;
            present++;
            refs.push_back(c);
        }
        if (!rd.zero(rd.pos, 7)) return fail(41);
        const int bcnt = popcnt64(pn.bulk_bitmap);
        if (bcnt < 4) return fail(42);                 // bulk groups have >= 4 roots
        if (present > 3) return fail(43);
        if (present + bcnt < 7) return fail(44);       // TYPE3 has 7..64 children
        if (present + bcnt > 64) return fail(45);
        if (pn.bulk_stage < 0 || pn.bulk_stage >= RAM_NUM) return fail(46);
        if (pn.bulk_stage >= stage) return fail(47);   // strictly lower stage
        if (pn.bulk_base & 1u) return fail(48);        // bulk base is even
        if (static_cast<uint64_t>(pn.bulk_base) + 2ULL * static_cast<uint64_t>(bcnt) >
            d_->cells[static_cast<size_t>(pn.bulk_stage)])
            return fail(49);
        for (int k = 0; k < 64; ++k) {
            if ((pn.bulk_bitmap >> k) & 1ULL) {
                ChildRef c;
                c.key = static_cast<uint8_t>(k);
                c.stage = pn.bulk_stage;
                c.bulk = true;
                c.cell = pn.bulk_base +
                         2u * static_cast<uint32_t>(popcnt64(pn.bulk_bitmap & low_mask(k)));

