"""Large-scale randomized differential test with heavy put churn."""
import json, os, random, subprocess, sys, time
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ref import norm, lpm

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
def run(payload):
    r = subprocess.run([sys.executable, os.path.join(ROOT,'run.py')],
                       input=json.dumps(payload).encode(), capture_output=True, cwd=ROOT)
    assert r.returncode == 0, r.stderr[:400]
    return json.loads(r.stdout.decode())

def build(rng, npfx, nq):
    ops = []; live = {}; answers = []
    pool = []
    for _ in range(npfx):
        style = rng.choice(['v4','v6','cluster','chain','rand'])
        if style == 'v4':
            a = '0'*24 + '%08x' % rng.getrandbits(32); l = rng.randint(0,32)
        elif style == 'v6':
            a = '%032x' % rng.getrandbits(128); l = rng.randint(0,128)
        elif style == 'cluster':
            a = '20010db8' + '%024x' % rng.getrandbits(96); l = rng.choice([16,17,32,48,64,65,96,128])
        elif style == 'chain':
            a = '20010db800000001' + '%016x' % rng.getrandbits(64); l = rng.choice([64,65,70,80,100,112,128])
        else:
            a = '%032x' % rng.getrandbits(128); l = rng.choice([0,1,16,17,64,65,128])
        pool.append((a,l))
    puts = 0
    qi = 0
    while puts < min(npfx*3, 20000) or qi < nq:
        if qi < nq and (puts >= min(npfx*3,20000) or rng.random() < 0.3):
            addrs = []
            for _ in range(rng.randint(1,4)):
                if pool and rng.random() < 0.6:
                    a = pool[rng.randrange(len(pool))][0]
                    a = '%032x' % (int(a,16) ^ rng.getrandbits(rng.choice([0,4,16,64,128])))
                else:
                    a = '%032x' % rng.getrandbits(128)
                addrs.append(a)
            ops.append(["query", addrs]); qi += len(addrs)
            for a in addrs: answers.append(lpm(live, int(a,16)))
        else:
            a,l = pool[rng.randrange(len(pool))]
            hop = rng.randint(0,4194302)
            ops.append(["put", a, l, hop]); puts += 1
            live[(norm(a,l), l)] = hop
    ops.append(["save"]); snap = dict(live)
    ops.append(["load_saved", 0])
    ops.append(["image_query", ['%032x' % (int(pool[i][0],16) ^ 0) for i in range(0, len(pool), max(1,len(pool)//12))] if pool else []])
    q2 = ['%032x' % (int(pool[i][0],16)) for i in range(0, len(pool), max(1,len(pool)//12))]
    ops.append(["query", q2])
    for a in q2: answers.append(lpm(live, int(a,16)))
    for a in q2: answers.append(lpm(snap, int(a,16)))
    # note: image_query comes before the live query in op order -> fix ordering
    return ops, answers

def main():
    seed = int(sys.argv[1]); iters = int(sys.argv[2])
    rng = random.Random(seed)
    bad = 0
    for it in range(iters):
        npfx = rng.choice([200, 600, 1500, 3000])
        ops, answers = build(rng, npfx, rng.randint(5, 40))
        # recompute the expected answers in the correct op order
        # (the builder interleaves, so just re-derive)
        resp = run({"cases":[{"ops":ops}]})
        res = resp['results'][0]
        # verify image lookups against the snapshot FIB
        snap = {}
        # rebuild the snapshot FIB by replaying puts before the save
        seen = False
        for o in ops:
            if o[0] == 'put' and not seen: snap[(norm(o[1],o[2]), o[2])] = o[3]
            elif o[0] == 'save': seen = True
        imgq = [o for o in ops if o[0] == 'image_query']
        idx = 0
        ok = True
        # live answers: recompute by replay
        live = {}
        pos = 0
        for o in ops:
            if o[0] == 'put': live[(norm(o[1],o[2]), o[2])] = o[3]
            elif o[0] == 'query':
                for a in o[1]:
                    if res['answers'][pos] != lpm(live, int(a,16)):
                        print('iter %d: live answer mismatch at %d' % (it,pos)); ok = False
                    pos += 1
            elif o[0] == 'image_query':
                for a in o[1]:
                    if res['answers'][pos] != lpm(snap, int(a,16)):
                        print('iter %d: image answer mismatch at %d: %r vs %r' % (it,pos,res['answers'][pos], lpm(snap,int(a,16)))); ok = False
                    pos += 1
        if res['loads'] != [True]:
            print('iter %d: loads' % it, res['loads']); ok = False
        if not ok: bad += 1
    print('BIG BAD:', bad)
    return 1 if bad else 0
sys.exit(main())
