bool Validator::finish() {
    // every charged cell is covered exactly once
    for (int s = 0; s < RAM_NUM; ++s) {
        const uint32_t n = d_->cells[static_cast<size_t>(s)];
        for (uint32_t c = 0; c < n; ++c)
            if (!covered_[static_cast<size_t>(s)][c]) return fail(101);
        if (n & 1u) {
            const std::bitset<256>& bits = d_->banks[static_cast<size_t>(s)].back();
            for (int i = 128; i < 256; ++i)
                if (bits[static_cast<size_t>(i)]) return fail(102);
        }
    }

    // complete FIB: distinct normalized prefixes within the documented bound
    std::vector<PrefixRec> fib = fib_;
    std::sort(fib.begin(), fib.end());
    for (size_t i = 1; i < fib.size(); ++i)
        if (fib[i].addr == fib[i - 1].addr && fib[i].len == fib[i - 1].len) return fail(103);
    if (fib.size() > static_cast<size_t>(MAX_FIB_ENTRIES)) return fail(104);

    // NI arrays tile the NI vector without holes; all entries used
    std::vector<std::pair<uint32_t, uint32_t> > ranges;
    for (size_t i = 0; i < nodes_.size(); ++i) {
        const PNode& n = nodes_[i];
        if (n.type == 4 || n.type == 5) continue;
        if (n.ni_count > 0) ranges.push_back(std::make_pair(n.ni_base, n.ni_count));
    }
    std::sort(ranges.begin(), ranges.end());
    uint64_t expect = 0;
    for (size_t i = 0; i < ranges.size(); ++i) {
        if (ranges[i].first != expect) return fail(105);
        expect += ranges[i].second;
    }
    if (expect != d_->nexthops.size()) return fail(106);

    // every dictionary pattern is used
    std::vector<uint8_t> used(d_->bitmaps.size(), 0);
    for (size_t i = 0; i < nodes_.size(); ++i) {
        const PNode& n = nodes_[i];
        if (n.type == 4 || n.type == 5) continue;
        if (n.bitmap_id < used.size()) used[n.bitmap_id] = 1;
    }
    for (size_t i = 0; i < used.size(); ++i)
        if (!used[i]) return fail(107);

    // the packed graph must be exactly the canonical structure of its own FIB
    Graph g = build_graph(fib);
    if ((g.root0 != nullptr) != (d_->root.stage >= 0)) return fail(108);
    if (g.root0 != nullptr) {
        std::map<std::pair<int, uint32_t>, size_t>::const_iterator it =
            index_.find(std::make_pair(d_->root.stage, d_->root.cell));
        if (it == index_.end()) return fail(109);
        if (!match(g.root0, it->second)) return fail(110);
    }
    if (g.front16.size() != d_->front16.size()) return fail(111);
    for (size_t i = 0; i < g.front16.size(); ++i) {
        if (g.front16[i].first != d_->front16[i].key) return fail(112);
        std::map<std::pair<int, uint32_t>, size_t>::const_iterator it =
            index_.find(std::make_pair(d_->front16[i].loc.stage, d_->front16[i].loc.cell));
        if (it == index_.end()) return fail(113);
        if (!match(g.front16[i].second, it->second)) return fail(114);
    }
    if (g.front64.size() != d_->front64.size()) return fail(115);
    for (size_t i = 0; i < g.front64.size(); ++i) {
        if (g.front64[i].first != d_->front64[i].key) return fail(116);
        std::map<std::pair<int, uint32_t>, size_t>::const_iterator it =
            index_.find(std::make_pair(d_->front64[i].loc.stage, d_->front64[i].loc.cell));
        if (it == index_.end()) return fail(117);
        if (!match(g.front64[i].second, it->second)) return fail(118);
    }
    return true;
}

